export type HeightfieldStats = {
  /** Minimum height. */
  "min": number;
  /** Maximum height. */
  "max": number;
  /** Mean height. */
  "mean": number;
  /** Count of non-finite samples (must be 0 for a valid field). */
  "non_finite": number;
};

export type TerrainGenerateResult = {
  /** Layer name. */
  "layer": string;
  /** Width, height in pixels. */
  "size_px": [number, number];
  /** Tile size and halo. */
  "tile_size": number;
  /** Halo. */
  "halo": number;
  /** Statistics. */
  "stats": HeightfieldStats;
  /** blake3 content hash (hex). */
  "content_hash": string;
  /** Wall time of the operation in milliseconds. */
  "duration_ms": number;
};

export type TerrainPreviewRequest = {
  /** Layer name. */
  "layer"?: string;
  /** Downsample factor exponent (0 = full, 1 = half, …). */
  "lod"?: number;
};

export type TerrainPreviewResult = {
  /** Width in samples. */
  "width": number;
  /** Height in samples. */
  "height": number;
  /** Height of sample value 0. */
  "min": number;
  /** Height of sample value 65535. */
  "max": number;
  /** The exact wire format of `jd_terrain::preview::Preview::to_bytes` (16-byte little-endian
header `u32 width, u32 height, f32 min, f32 max` followed by row-major u16 samples),
standard base64 with padding. One decoder serves both transports. */
  "bytes_base64": string;
};

export type TerrainScatterRequest = {
  /** 0..1 density mask layer (a biome class mask, wetness, a painted mask…). */
  "mask": string;
  /** Height layer sampled for `z` (null = 0). */
  "height"?: string | null;
  /** Output `.csv`, `.json` or `.glb` (proxy mesh instanced with `EXT_mesh_gpu_instancing`);
relative paths resolve against the project's `exports/`. */
  "path": string;
  /** Target spacing between points in metres (grid cell size); must be ≥ one sample spacing. */
  "spacing_m": number;
  /** Random offset inside the cell, 0 (regular grid) .. 1 (anywhere in the cell). */
  "jitter"?: number;
  /** Seed for the jitter and the density test. */
  "seed"?: number;
};

export type TerrainScatterResult = {
  /** Written file. */
  "path": string;
  /** Points written. */
  "count": number;
  /** Bytes written. */
  "bytes": number;
  /** Candidates per axis the grid had. */
  "spacing_m": number;
};

export type TerrainStatsRequest = {
  /** Layer name. */
  "layer"?: string;
};

export type TerrainStatsResult = {
  /** Layer name. */
  "layer": string;
  /** Width, height in pixels. */
  "size_px": [number, number];
  /** Tile size and halo. */
  "tile_size": number;
  /** Halo. */
  "halo": number;
  /** Statistics. */
  "stats": HeightfieldStats;
  /** blake3 content hash (hex). */
  "content_hash": string;
  /** Wall time of the operation in milliseconds. */
  "duration_ms": number;
};

export type NodeParams_jd_analysis_curvature_1 = {
  /** Curvature (1/m) that maps to ±1; smaller values exaggerate. */
  "scale"?: number;
  /** Stencil half-width in samples (1..=16): 1 reacts to every bump, larger radii read
ridges and valleys at landscape scale. */
  "radius_px"?: number;
};

export type FlowMethod = "d8" | "dinf" | "mfd";

export type NodeParams_jd_analysis_flow_1 = {
  /** Output ln(1 + area) / ln(1 + N) in 0..1 (true) or the raw upstream cell count (false). */
  "log_scale"?: boolean;
  /** Routing: `d8` (single steepest neighbour), `dinf` (Tarboton facets, smoother streams) or `mfd` (Freeman, most diffuse). */
  "method"?: FlowMethod;
};

export type NodeParams_jd_analysis_slope_1 = {
  /** Slope that maps to 1.0 in the mask (degrees, (0, 90]). */
  "max_deg"?: number;
};

export type BiomeRule = {
  /** Display name (e.g. "alpine meadow"). */
  "name": string;
  /** Height band in metres [min, max). */
  "height_m"?: [number, number] | null;
  /** Slope band in 0..1 (the `jd.analysis.slope@1` scale, 1 = 90°) [min, max). */
  "slope"?: [number, number] | null;
  /** Wetness band in 0..1 (the `jd.hydrology.wetness@1` index) [min, max). */
  "wetness"?: [number, number] | null;
};

export type NodeParams_jd_biome_classify_1 = {
  /** Rules in priority order; class ids are 1-based positions, 0 = unclassified. Empty = a
temperate default set (beach, grassland, forest, rock, snow). */
  "rules"?: BiomeRule[];
};

export type NodeParams_jd_erosion_droplet_1 = {
  /** Number of droplets (1..=5 000 000). Aim for 1–2 per cell: 512² wants ~400 000; fewer gives
diffuse, unstructured lowering, more deepens the same gullies. */
  "droplets"?: number;
  /** Seed. */
  "seed"?: number;
  /** Steps a droplet may travel before it is dropped (8..=256). */
  "max_steps"?: number;
  /** Direction inertia 0..1 (0 follows the gradient exactly). */
  "inertia"?: number;
  /** Sediment capacity factor. */
  "capacity"?: number;
  /** Minimum capacity so droplets on flats still carry a little. */
  "min_capacity"?: number;
  /** Fraction of surplus sediment deposited per step, 0..1. */
  "deposit"?: number;
  /** Fraction of the capacity deficit eroded per step, 0..1. */
  "erode"?: number;
  /** Water lost per step, 0..1. */
  "evaporation"?: number;
  /** Gravity (speed gain per unit drop). */
  "gravity"?: number;
  /** Erosion brush radius in cells (1..=8). */
  "radius"?: number;
};

export type NodeParams_jd_erosion_hydraulic_1 = {
  /** Simulation steps (1..=2000). */
  "iterations"?: number;
  /** Time step in seconds ((0, 1]; 0.02 is stable for the pipe model). */
  "dt"?: number;
  /** Rain in metres of water per second. */
  "rain_rate"?: number;
  /** Evaporation per second (fraction of depth). */
  "evaporation"?: number;
  /** Sediment capacity constant Kc. */
  "capacity_k"?: number;
  /** Dissolving constant Ks. */
  "dissolve_k"?: number;
  /** Deposition constant Kd. */
  "deposit_k"?: number;
  /** Suspended sediment cap as a fraction of water depth (excess settles the same step). */
  "max_concentration"?: number;
};

export type NodeParams_jd_erosion_stream_power_1 = {
  /** Erodibility K: metres of incision per step for unit drainage area and unit slope
(`dz = -K·A^m·S`, A in m², S dimensionless). 1e-3 carves visible valleys on a 5 km world
in 20 steps; 1e-4 is subtle, 1e-2 is a badlands. */
  "k"?: number;
  /** Area exponent m (0.3–0.6 in nature; n is fixed at 1 for the implicit solve). */
  "m"?: number;
  /** Uniform uplift per step in metres (0 = none); outlets rise too, so base level is kept. */
  "uplift_m"?: number;
  /** Steps (1..=1000). */
  "iterations"?: number;
  /** Flow routing used for the drainage area. */
  "method"?: FlowMethod;
};

export type NodeParams_jd_erosion_thermal_1 = {
  /** Angle of repose in degrees (sand ≈ 30–35, scree ≈ 35–40). */
  "talus_deg"?: number;
  /** Jacobi steps (1..=1000); more steps move material further. */
  "iterations"?: number;
  /** Fraction of the excess that moves per step, (0, 0.25]; 0.25 is the stable maximum. */
  "rate"?: number;
};

export type NodeParams_jd_filter_blur_1 = {
  /** Box-blur radius in pixels (1..=4; must not exceed the world's tile halo). */
  "radius"?: number;
};

export type NodeParams_jd_filter_terrace_1 = {
  /** Step height in metres (> 0). */
  "step_m"?: number;
  /** 0 = hard steps, 1 = untouched; in between blends the step edge over that fraction of the riser. */
  "softness"?: number;
  /** Shift the step boundaries by this many metres. */
  "offset_m"?: number;
};

export type NodeParams_jd_hydrology_fill_1 = {
  /** Extra rise per step across filled flats so they still drain (metres; 0 = perfectly flat lakes). */
  "epsilon_m"?: number;
};

export type NodeParams_jd_hydrology_rivers_1 = {
  /** Log-scaled flow accumulation (0..1) above which a cell is a river channel. */
  "threshold"?: number;
  /** Incision depth at the largest rivers, metres. */
  "depth_m"?: number;
  /** Flow routing used to find channels: `d8`, `dinf` (fewer parallel-line artefacts) or `mfd` (wide, diffuse). */
  "method"?: FlowMethod;
};

export type NodeParams_jd_hydrology_sea_level_1 = {
  /** Sea level in metres (world heights). */
  "level_m"?: number;
  /** Shoreline softness: the ocean mask fades from 1 to 0 over this many metres above the level. */
  "shore_m"?: number;
};

export type NodeParams_jd_hydrology_wetness_1 = Record<string, unknown>;

export type NodeParams_jd_input_heightmap_1 = {
  /** File inside the project's `assets/` directory (png, exr, tif/tiff, r16, r32). */
  "path": string;
  /** Height range the full 16-bit span maps to (quantised PNG/TIFF/r16); ignored for float data. */
  "range_m"?: [number, number] | null;
  /** Width and height in pixels — required for headerless RAW files. */
  "size_px"?: [number, number] | null;
  /** Row 0 of the file is north (true, the usual image convention) or south (the field convention). */
  "north_up"?: boolean;
  /** Sample value meaning "no data" (filled with the lowest valid height). Default: the GeoTIFF
`GDAL_NODATA` tag when present, otherwise none; non-finite samples are always treated as nodata. */
  "nodata"?: number | null;
};

export type NodeParams_jd_mask_class_1 = {
  /** Class id to select (1-based rule position from `jd.biome.classify@1`). */
  "id": number;
};

export type NodeParams_jd_math_add_1 = Record<string, unknown>;

export type NodeParams_jd_math_multiply_1 = Record<string, unknown>;

export type NodeParams_jd_math_remap_1 = {
  /** Input range mapped from. */
  "from"?: [number, number];
  /** Output range mapped to. */
  "to"?: [number, number];
  /** Clamp to the output range. */
  "clamp"?: boolean;
};

export type NodeParams_jd_math_scale_1 = {
  /** Multiplier. */
  "factor"?: number;
};

export type NodeParams_jd_noise_fbm_1 = {
  /** Lattice. */
  "kind"?: NoiseKind;
  /** Fractal combinator. */
  "fractal"?: FractalKind;
  /** Seed (combined with the world seed by the caller when desired). */
  "seed"?: number;
  /** Feature size in metres (wavelength of the first octave). */
  "feature_size_m"?: number;
  /** Octave count (1–16). */
  "octaves"?: number;
  /** Frequency multiplier per octave. */
  "lacunarity"?: number;
  /** Amplitude multiplier per octave. */
  "gain"?: number;
  /** Output height range in metres: noise ∈ [-1,1] maps to [min, max]. */
  "height_range_m"?: [number, number];
  /** Offset of the sampling origin in metres. */
  "offset_m"?: [number, number];
};

export type NodeParams_jd_output_height_1 = {
  /** Layer name the result is published under. */
  "layer"?: string;
};

export type StrokeMode = "raise" | "smooth" | "flatten";

export type Stroke = {
  /** Polyline in layer metres: `[u east, v north]` from the south-west corner (row 0 = south). */
  "points": ([number, number])[];
  /** Brush radius in metres. */
  "radius_m": number;
  /** Height added at the centre for `raise` (negative lowers), metres. */
  "strength_m"?: number;
  /** Brush behaviour (default `raise`). */
  "mode"?: StrokeMode;
  /** Blend factor 0..1 for `smooth` / `flatten` (default 0.5). */
  "amount"?: number;
};

export type NodeParams_jd_sculpt_strokes_1 = {
  /** Recorded brush strokes, applied in order on top of the input. */
  "strokes"?: Stroke[];
};

/** Request and result types of every core operation, keyed by op id. */
export interface JdOps {
  /** Run a benchmark scene (S1: fBm + ridged + add + thermal×50) with the real kernels; per-stage wall time, peak RSS, content hash */
  "diag.bench": { request: DiagBenchRequest; result: DiagBenchResult };
  /** Report host environment and detected tools */
  "diag.env": { request: DiagEnvRequest; result: DiagEnvResult };
  /** Add a node (journaled) */
  "graph.add_node": { request: GraphAddNodeRequest; result: GraphAddNodeResult };
  /** Push one element onto an array parameter (brush strokes): journaled with just the element, so a long sculpt session grows the journal linearly */
  "graph.append_param": { request: GraphAppendParamRequest; result: GraphAppendParamResult };
  /** Connect an output to an input (journaled; rejects bad ports, type mismatches and cycles) */
  "graph.connect": { request: GraphConnectRequest; result: GraphConnectResult };
  /** Remove an edge (journaled) */
  "graph.disconnect": { request: GraphDisconnectRequest; result: GraphDisconnectResult };
  /** Validate and evaluate the graph incrementally; publishes output nodes as layers (`<layer>#lod<N>` when lod > 0) */
  "graph.evaluate": { request: GraphEvaluateRequest; result: GraphEvaluateResult };
  /** Start graph.evaluate on a worker thread and return at once with `status: accepted` + `job_id`; follow it with jobs.list, cancel with jobs.cancel, collect the envelope with jobs.result */
  "graph.evaluate_async": { request: GraphEvaluateAsyncRequest; result: GraphEvaluateAsyncResult };
  /** List available node kinds with ports and parameter schemas */
  "graph.kinds": { request: GraphKindsRequest; result: GraphKindsResult };
  /** Nodes and edges of the open project's graph */
  "graph.list": { request: GraphListRequest; result: GraphListResult };
  /** Move a node on the editor canvas (journaled) */
  "graph.move_node": { request: GraphMoveNodeRequest; result: GraphMoveNodeResult };
  /** Re-apply the last undone graph edit (journaled as graph.restore) */
  "graph.redo": { request: GraphRedoRequest; result: GraphRedoResult };
  /** Remove a node and its edges (journaled) */
  "graph.remove_node": { request: GraphRemoveNodeRequest; result: GraphRemoveNodeResult };
  /** Bypass or un-bypass a node (journaled) */
  "graph.set_bypass": { request: GraphSetBypassRequest; result: GraphSetBypassResult };
  /** Set (or null to reset) a node parameter (journaled; validated against the kind's schema) */
  "graph.set_param": { request: GraphSetParamRequest; result: GraphSetParamResult };
  /** Take back the last graph edit (journaled as graph.restore) */
  "graph.undo": { request: GraphUndoRequest; result: GraphUndoResult };
  /** Request cancellation of a running job; it stops at the next node or kernel iteration with E_CANCELLED */
  "jobs.cancel": { request: JobsCancelRequest; result: JobsCancelResult };
  /** Running jobs with progress (steps done/total, current node) — poll while an evaluation runs */
  "jobs.list": { request: JobsListRequest; result: JobsListResult };
  /** State of a job: running (progress), done (the finished op's envelope, handed over once) or unknown */
  "jobs.result": { request: JobsResultRequest; result: JobsResultResult };
  /** Evict the oldest cached layer blobs until the project's cache fits `settings.cache_limit_bytes` (the cache is disposable); reports what is left */
  "project.cache_gc": { request: ProjectCacheGcRequest; result: ProjectCacheGcResult };
  /** Close the open project (unsaved changes stay in the journal) */
  "project.close": { request: ProjectCloseRequest; result: ProjectCloseResult };
  /** Create a new project directory and open it */
  "project.create": { request: ProjectCreateRequest; result: ProjectCreateResult };
  /** Copy a file (DEM, heightmap, texture) into the project's assets/ so nodes can reference it by name */
  "project.import_asset": { request: ProjectImportAssetRequest; result: ProjectImportAssetResult };
  /** Describe the open project */
  "project.info": { request: ProjectInfoRequest; result: ProjectInfoResult };
  /** Open an existing project */
  "project.open": { request: ProjectOpenRequest; result: ProjectOpenResult };
  /** Replay unsaved journal entries found when the project was opened, then save (entries that fail stay pending unless discard_failed) */
  "project.recover": { request: ProjectRecoverRequest; result: ProjectRecoverResult };
  /** Write the open project to disk */
  "project.save": { request: ProjectSaveRequest; result: ProjectSaveResult };
  /** Rename the open project */
  "project.set_name": { request: ProjectSetNameRequest; result: ProjectSetNameResult };
  /** Change project settings (autosave interval, cache limit, preview LOD); fields left out keep their value — journaled like every mutation */
  "project.set_settings": { request: ProjectSetSettingsRequest; result: ProjectSetSettingsResult };
  /** Write a layer as EXR (f32), PNG16, RAW r16 or r32 with a JSON sidecar */
  "terrain.export_heightmap": { request: TerrainExportHeightmapRequest; result: TerrainExportHeightmapResult };
  /** Write a layer as a grid mesh — .glb (normals, UVs, PBR material with baked base-colour texture), .obj, binary .stl, binary .ply with vertex colours, .usda, or .usdz (needs usdzip) — metres, +Y up, centred on the world */
  "terrain.export_mesh": { request: TerrainExportMeshRequest; result: TerrainExportMeshResult };
  /** Write a Unity or Unreal terrain import set: heightmap in the engine's encoding and row order, one 8-bit weightmap per mask layer, and a README with the computed Terrain Height / Z scale */
  "terrain.export_profile": { request: TerrainExportProfileRequest; result: TerrainExportProfileResult };
  /** Generate a noise heightfield for the open project's world and store it as a layer */
  "terrain.generate": { request: TerrainGenerateRequest; result: TerrainGenerateResult };
  /** Downsampled u16 preview of a layer (base64) for agents and viewers */
  "terrain.preview": { request: TerrainPreviewRequest; result: TerrainPreviewResult };
  /** Scatter instance points over the world from a 0..1 density mask layer (stratified jittered grid, deterministic by seed) and write them as CSV or JSON with heights, or as GLB instances */
  "terrain.scatter": { request: TerrainScatterRequest; result: TerrainScatterResult };
  /** Statistics and content hash of a layer */
  "terrain.stats": { request: TerrainStatsRequest; result: TerrainStatsResult };
}

export type OpId = keyof JdOps;

/** Parameter types of every built-in node kind. */
export interface NodeKinds {
  "jd.analysis.curvature@1": NodeParams_jd_analysis_curvature_1;
  "jd.analysis.flow@1": NodeParams_jd_analysis_flow_1;
  "jd.analysis.slope@1": NodeParams_jd_analysis_slope_1;
  "jd.biome.classify@1": NodeParams_jd_biome_classify_1;
  "jd.erosion.droplet@1": NodeParams_jd_erosion_droplet_1;
  "jd.erosion.hydraulic@1": NodeParams_jd_erosion_hydraulic_1;
  "jd.erosion.stream_power@1": NodeParams_jd_erosion_stream_power_1;
  "jd.erosion.thermal@1": NodeParams_jd_erosion_thermal_1;
  "jd.filter.blur@1": NodeParams_jd_filter_blur_1;
  "jd.filter.terrace@1": NodeParams_jd_filter_terrace_1;
  "jd.hydrology.fill@1": NodeParams_jd_hydrology_fill_1;
  "jd.hydrology.rivers@1": NodeParams_jd_hydrology_rivers_1;
  "jd.hydrology.sea_level@1": NodeParams_jd_hydrology_sea_level_1;
  "jd.hydrology.wetness@1": NodeParams_jd_hydrology_wetness_1;
  "jd.input.heightmap@1": NodeParams_jd_input_heightmap_1;
  "jd.mask.class@1": NodeParams_jd_mask_class_1;
  "jd.math.add@1": NodeParams_jd_math_add_1;
  "jd.math.multiply@1": NodeParams_jd_math_multiply_1;
  "jd.math.remap@1": NodeParams_jd_math_remap_1;
  "jd.math.scale@1": NodeParams_jd_math_scale_1;
  "jd.noise.fbm@1": NodeParams_jd_noise_fbm_1;
  "jd.output.height@1": NodeParams_jd_output_height_1;
  "jd.sculpt.strokes@1": NodeParams_jd_sculpt_strokes_1;
}
